// 어피치 샘플 테마(26.1.0)의 colors.xml, 말풍선 9-patch, 앱 아이콘. 아무것도 넣지 않았을 때 미리보기 기본값
window.SAMPLE={"colorsXml": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<resources>\n\n    <!-- 어피치 -->\n\n    <!-- Header : 메인탭 헤더 타이틀 -->\n    <color name=\"theme_header_color\">#664242</color>                            <!--Default-->\n\n    <!-- Section Title : 섹션 헤더 타이틀 -->\n    <color name=\"theme_section_title_color\">#F66C6C</color>                     <!--Default-->\n\n    <!-- Title : 이름 -->\n    <color name=\"theme_title_color\">#664242</color>                             <!--Default-->\n    <color name=\"theme_title_pressed_color\">#B06B6B</color>                     <!--Pressed-->\n\n    <!-- Paragraph : 라스트메세지 -->\n    <color name=\"theme_paragraph_color\">#805959</color>                         <!--Default-->\n    <color name=\"theme_paragraph_pressed_color\">#B06B6B</color>                 <!--Pressed-->\n\n    <!-- Description : 상태메세지 -->\n    <color name=\"theme_description_color\">#805959</color>                       <!--Default-->\n    <color name=\"theme_description_pressed_color\">#B06B6B</color>               <!--Pressed-->\n\n    <!-- Feature : 서비스/피처별 컬러 -->\n\n    <!-- Primary : 멜론/선물하기 등 버튼 텍스트 -->\n    <color name=\"theme_feature_primary_color\">#805959</color>                   <!--Default-->\n    <color name=\"theme_feature_primary_pressed_color\">#B06B6B</color>           <!--Pressed-->\n\n    <!-- Services : Browse 3탭 -->\n    <color name=\"theme_feature_browse_tab_color\">#D49B9B</color>                <!--Default-->\n    <color name=\"theme_feature_browse_tab_focused_color\">#664242</color>        <!--Focused-->\n\n\n    <!-- Background -->\n    <!-- 기본 -->\n    <color name=\"theme_background_color\">#FFDEDE</color>\n    <!-- 채팅방 -->\n    <color name=\"theme_chatroom_background_color\">#FFDEDE</color>\n    <!-- 잠금화면 -->\n    <color name=\"theme_passcode_background_color\">#FCC5C5</color>\n\n\n    <!-- Cell Color -->\n\n    <!-- Header : 메인탭 헤더 타이틀 셀 -->\n    <color name=\"theme_header_cell_color\">#FFDEDE</color>\n\n    <!-- Body : 기본리스트 & 콘텐츠영역 셀 -->\n    <color name=\"theme_body_cell_color\">#00FFDEDE</color>\n    <color name=\"theme_body_cell_pressed_color\">#FFB3B3</color>\n    <color name=\"theme_body_cell_border_color\">#26664242</color>\n\n    <!-- Body Secondary : 발견 & 더보기 콘텐츠 영역 셀 -->\n    <color name=\"theme_body_secondary_cell_color\">#FFDEDE</color>\n\n    <!-- Tab : 메인탭 탭바 -->\n    <color name=\"theme_maintab_cell_color\">#00FFFFFF</color>\n    <color name=\"theme_tab_lightbannerbadge_background_color\">#664242</color>\n\n    <!-- Tab : 배너 -->\n    <color name=\"theme_tab_bannerbadge_background_color\">#664142</color>\n\n\n    <!-- Elements Color -->\n\n    <!-- Direct Share BG -->\n    <color name=\"theme_direct_share_color\">#664242</color>\n    <color name=\"theme_direct_share_button_color\">#E87D7D</color>\n    <color name=\"theme_direct_share_background_color\">#FFF2F2</color>\n\n    <!-- Notification Popup/Toast -->\n    <color name=\"theme_notification_color\">#664242</color>\n    <color name=\"theme_notification_background_color\">#FFD4D4</color>\n    <color name=\"theme_notification_background_pressed_color\">#FFB3B3</color>\n\n    <!-- Passcode -->\n    <color name=\"theme_passcode_color\">#664242</color>\n\n    <color name=\"theme_passcode_keypad_color\">#664242</color>\n    <color name=\"theme_passcode_keypad_pressed_color\">#CCB8B8</color>\n    <color name=\"theme_passcode_keypad_background_color\">#FFF2F2</color>\n    <color name=\"theme_passcode_keypad_pressed_background_color\">#99FFDEDE</color>\n\n    <color name=\"theme_passcode_pattern_line_color\">#FCC5C5</color>\n\n\n    <!-- Chatroom -->\n\n    <!-- Chat Bubble -->\n\n    <!-- Me -->\n    <color name=\"theme_chatroom_bubble_me_color\">#FFFFFF</color>\n\n    <!-- You -->\n    <color name=\"theme_chatroom_bubble_you_color\">#4D4D4D</color>\n\n    <!-- Chat Unread Count -->\n    <color name=\"theme_chatroom_unread_count_color\">#FF7F7F</color>\n\n    <!-- Input Bar -->\n    <color name=\"theme_chatroom_input_bar_color\">#191919</color>\n    <color name=\"theme_chatroom_input_bar_background_color\">#FFFFFF</color>\n    <color name=\"theme_chatroom_input_bar_menu_icon_color\">#E86464</color>\n    <color name=\"theme_chatroom_input_bar_menu_button_color\">#0A000000</color>\n    <color name=\"theme_chatroom_input_bar_send_icon_color\">#FFFFFF</color>\n    <color name=\"theme_chatroom_input_bar_send_button_color\">#FF7F7F</color>\n\n</resources>\n", "bubbles": {"theme_chatroom_bubble_me_01_image.9": "", "theme_chatroom_bubble_me_02_image.9": "", "theme_chatroom_bubble_you_01_image.9": "", "theme_chatroom_bubble_you_02_image.9": ""}, "icons": {"foreground": "", "background": ""}};
